const naira = (n:number) => `₦${n.toLocaleString("en-NG")}`;
const monthly = (p:number, months=6) => Math.ceil((p * 1.08) / months);
const getCart = ():CartItem[] => { try { return JSON.parse(localStorage.getItem("gs-cart") || "[]"); } catch { return []; } };

function Logo() { return <Link href="/" className="brand" data-testid="link-logo"><span className="brand-mark">G</span><span>The Gentlemen<small>Series / gadgets on your terms</small></span></Link>; }

function ProductArt({product, large=false}:{product:Product;large?:boolean}) {
  return <div className={`product-shape ${product.image}`} style={{"--product-a": product.id.includes("iphone") ? "#a9b8d9" : product.id.includes("pixel") ? "#cce1cf" : product.id.includes("mac") ? "#ad9fdf" : product.id.includes("anker") ? "#384463" : "#7084cc","--product-b": product.id.includes("iphone") ? "#4e5a9a" : product.id.includes("pixel") ? "#537d76" : "#263b80"} as CSSProperties} aria-label={`${product.name} product illustration`} /> 
}

function Nav({cartCount,onCart}:{cartCount:number;onCart:()=>void}) {
  const [open,setOpen]=useState(false); const [location]=useLocation();
  const links=[["/shop","Shop"],["/plans","Plans"],["/how-it-works","How it works"],["/about","Our story"],["/contact","Contact"]];
  return <><div className="topbar"><div className="container"><span>Thoughtful gadgets. Flexible payments. Made for Nigeria.</span><span>Demo marketplace · No real payments</span></div></div><nav className="nav"><div className="container nav-inner"><Logo/><div className={`nav-links ${open?"open":""}`}>{links.map(([href,label])=><Link key={href} href={href} onClick={()=>setOpen(false)} className={location===href?"active":""} data-testid={`link-nav-${label.toLowerCase().replaceAll(" ","-")}`}>{label}</Link>)}</div><div className="nav-actions"><Link href="/login" className="btn btn-ghost" data-testid="link-login-nav"><UserRound size={15}/> Sign in</Link><button className="icon-button" onClick={onCart} aria-label="Open cart" data-testid="button-open-cart"><ShoppingBag size={18}/>{cartCount>0&&<span className="cart-count">{cartCount}</span>}</button><button className="menu-button" onClick={()=>setOpen(!open)} aria-label="Toggle navigation" data-testid="button-mobile-menu">{open?<X size={19}/>:<Menu size={19}/>}</button></div></div></nav></>;
}

function Footer(){ return <footer className="footer"><div className="container footer-grid"><div><Logo/><p>Good gadgets, clear terms, and a little more room to breathe. Built for how Nigeria actually shops.</p></div><div><h4>Explore</h4><Link href="/shop">Shop gadgets</Link><br/><Link href="/plans">Payment plans</Link><br/><Link href="/how-it-works">How it works</Link></div><div><h4>Company</h4><Link href="/about">Our story</Link><br/><Link href="/contact">Contact</Link><br/><Link href="/apply">Apply now</Link></div><div><h4>Need a hand?</h4><p>Mon–Fri, 9am–5pm<br/>hello@thegentlemen.ng<br/>Lagos, Nigeria</p></div></div><div className="container footer-bottom"><span>© 2024 The Gentlemen Series</span><span>All prices and plans shown are demonstration data.</span></div></footer>; }

function ProductCard({product,onAdd,onToast}:{product:Product;onAdd:(p:Product)=>void;onToast:(s:string)=>void}) {
  const [saved,setSaved]=useState(false);
  return <article className="product-card reveal" data-testid={`card-product-${product.id}`}><div className="product-visual"><span className="product-badge">{product.badge||"Ready to ship"}</span><button className={`heart ${saved?"saved":""}`} onClick={()=>{setSaved(!saved);onToast(saved?"Removed from saved gadgets":"Saved to your wishlist")}} aria-label={`Save ${product.name}`} data-testid={`button-save-${product.id}`}><Heart size={15} fill={saved?"currentColor":"none"}/></button><ProductArt product={product}/></div><div className="product-copy"><span className="brandline">{product.brand} · {product.category}</span><h3>{product.name}</h3><div className="price">{naira(product.price)}</div><div className="installment">From {naira(monthly(product.price))}/month · 6 months</div><div className="card-actions"><Link href={`/product/${product.id}`} className="btn btn-ghost" data-testid={`link-product-${product.id}`}>View details</Link><button className="btn btn-primary" onClick={()=>onAdd(product)} data-testid={`button-add-${product.id}`}>Add to cart</button></div></div></article>;
}

function Home({onAdd,onToast}:{onAdd:(p:Product)=>void;onToast:(s:string)=>void}) {
  return <><section className="hero"><div className="container hero-grid"><div className="reveal"><div className="eyebrow">A better way to buy tech</div><h1>Get the gadget you want. <em>Pay at your pace.</em></h1><p>Phones, laptops, tablets and more—picked with care, priced clearly, and available through simple installment plans that fit real life.</p><div className="hero-actions"><Link href="/shop" className="btn btn-mint" data-testid="link-hero-shop">Browse gadgets <ArrowRight size={16}/></Link><Link href="/how-it-works" className="btn btn-ghost" data-testid="link-hero-how">See how it works</Link></div><div className="trust-row"><span className="trust-item"><ShieldCheck size={15}/> Clear pricing</span><span className="trust-item"><Clock3 size={15}/> Flexible terms</span><span className="trust-item"><Truck size={15}/> Delivered nationwide</span></div></div><div className="hero-art reveal delay-1"><div className="hero-device"><div className="device-screen"><span>your next<br/>chapter.</span></div></div><div className="hero-note"><span className="eyebrow">Your monthly plan</span><b>₦142,300</b><small>6 payments · no surprises</small></div></div></div></section><section className="section-tight"><div className="container numbers"><div className="number-card"><b>15+</b><span>carefully chosen gadgets</span></div><div className="number-card"><b>3–12</b><span>months to spread your payments</span></div><div className="number-card"><b>₦0</b><span>hidden fees in our demo plans</span></div></div></section><section className="section band"><div className="container"><div className="section-head"><div><div className="eyebrow">Why people choose us</div><h2>Tech shopping,<br/>without the tension.</h2></div><p className="muted">The marketplace for people who want the good stuff and a payment plan they can actually understand.</p></div><div className="feature-grid"><div className="feature-card"><BadgeCheck size={24}/><h3>Terms in plain English</h3><p className="muted">See exactly what you pay each month before you apply. No fine-print gymnastics.</p></div><div className="feature-card"><Zap size={24}/><h3>Move at your pace</h3><p className="muted">Choose a plan from 3 to 12 months based on what works for you.</p></div><div className="feature-card"><Headphones size={24}/><h3>Real human support</h3><p className="muted">Questions? Talk to a person who knows the product and the process.</p></div></div></div></section><section className="section"><div className="container"><div className="section-head"><div><div className="eyebrow">The good stuff</div><h2>Ready when you are.</h2></div><Link href="/shop" className="btn btn-ghost" data-testid="link-home-view-all">View all gadgets <ArrowRight size={15}/></Link></div><div className="product-grid">{products.slice(0,4).map(p=><ProductCard key={p.id} product={p} onAdd={onAdd} onToast={onToast}/>)}</div></div></section><section className="section mint-band"><div className="container section-head"><div><div className="eyebrow">Still deciding?</div><h2>Start with a number<br/>that feels comfortable.</h2></div><div><p>Use our calculator to see what your favorite gadget could look like month to month.</p><Link href="/plans" className="btn btn-primary" data-testid="link-home-plans">Explore payment plans <ArrowRight size={15}/></Link></div></div></section></>;
}

function Shop({onAdd,onToast}:{onAdd:(p:Product)=>void;onToast:(s:string)=>void}) {
  const [query,setQuery]=useState(""); const [category,setCategory]=useState("All"); const [brands,setBrands]=useState<string[]>([]); const [sort,setSort]=useState("featured"); const [max,setMax]=useState(1500000);
  const cats=["All","Phones","Laptops","Tablets","Gaming","Accessories"]; const brandList=["Apple","Samsung","Google","Sony","Lenovo","HP","Anker","Microsoft","Nintendo"];
  const filtered=useMemo(()=>products.filter(p=>(category==="All"||p.category===category)&&p.price<=max&&(!query||`${p.name} ${p.brand}`.toLowerCase().includes(query.toLowerCase()))&&(brands.length===0||brands.includes(p.brand))).sort((a,b)=>sort==="price-low"?a.price-b.price:sort==="price-high"?b.price-a.price:a.name.localeCompare(b.name)),[query,category,brands,sort,max]);
  return <><PageHero eyebrow="The collection" title="Good gadgets, no guesswork." text="Browse the phones, laptops, tablets, consoles and accessories we would recommend to a friend."/><section className="section-tight"><div className="container catalog-layout"><aside className="filters"><h3>Filter your shortlist</h3><div className="filter-block"><div className="small muted">Category</div>{cats.map(c=><label key={c}><input type="radio" name="category" checked={category===c} onChange={()=>setCategory(c)} data-testid={`filter-category-${c.toLowerCase()}/>`}/>{c}</label>)}</div><div className="filter-block"><div className="small muted">Brand</div>{brandList.map(b=><label key={b}><input type="checkbox" checked={brands.includes(b)} onChange={()=>setBrands(brands.includes(b)?brands.filter(x=>x!==b):[...brands,b])} data-testid={`filter-brand-${b.toLowerCase()}`}/>{b}</label>)}</div><div className="filter-block"><div className="small muted">Up to {naira(max)}</div><input type="range" className="range" min="65000" max="1500000" step="25000" value={max} onChange={e=>setMax(Number(e.target.value))} aria-label="Maximum price" data-testid="filter-price"/></div></aside><main><div className="catalog-toolbar"><div className="searchbox"><Search size={16}/><input className="input" value={query} onChange={e=>setQuery(e.target.value)} placeholder="Search gadgets or brands" aria-label="Search gadgets" data-testid="input-search-products"/></div><select className="select" value={sort} onChange={e=>setSort(e.target.value)} aria-label="Sort products" data-testid="select-sort-products"><option value="featured">Sort: Featured</option><option value="price-low">Price: low to high</option><option value="price-high">Price: high to low</option><option value="name">Name A–Z</option></select></div><p className="small muted" data-testid="text-product-count">{filtered.length} gadgets to explore</p>{filtered.length?<div className="product-grid">{filtered.map(p=><ProductCard key={p.id} product={p} onAdd={onAdd} onToast={onToast}/>)}</div>:<div className="empty"><Search size={28}/><h3 className="display">Nothing matches that shortlist.</h3><p className="muted">Try a different brand, category, or price range.</p><button className="btn btn-primary" onClick={()=>{setQuery("");setCategory("All");setBrands([]);setMax(1500000)}} data-testid="button-reset-filters">Reset filters</button></div>}</main></div></section></>;
}

function PageHero({eyebrow,title,text}:{eyebrow:string;title:string;text:string}) { return <section className="page-hero"><div className="container"><div className="crumbs"><Link href="/">Home</Link><ChevronRight size={12}/><span>{eyebrow}</span></div><div className="eyebrow" style={{marginTop:28}}>{eyebrow}</div><h1 className="display">{title}</h1><p>{text}</p></div></section>; }

function ProductDetail({onAdd,onToast}:{onAdd:(p:Product)=>void;onToast:(s:string)=>void}) {
  const [,params]=useRoute("/product/:id"); const product=products.find(p=>p.id===params?.id)||products[0]; const [months,setMonths]=useState(6); const [color,setColor]=useState(product.colors[0]);
  return <><PageHero eyebrow={product.category} title={product.name} text={product.description}/><section className="section"><div className="container detail-grid"><div className="detail-visual"><ProductArt product={product} large/></div><div className="detail-copy"><div className="eyebrow">{product.brand} · {product.category}</div><h1>{product.name}</h1><div className="price">{naira(product.price)}</div><div className="installment">Or from {naira(monthly(product.price,months))} monthly · demonstration plan</div><div className="small muted">Colour</div><div className="option-row">{product.colors.map(c=><button key={c} className={`option ${color===c?"active":""}`} onClick={()=>setColor(c)} data-testid={`button-color-${c.toLowerCase().replaceAll(" ","-")}`}>{c}</button>)}</div><div className="calculator"><h3>Make it yours, month by month.</h3><p className="fine muted">Choose a term. We show the full picture upfront.</p><input className="range" type="range" min="3" max="12" value={months} onChange={e=>setMonths(Number(e.target.value))} aria-label="Number of monthly payments" data-testid="input-plan-months"/><div className="calc-row"><div><span className="small">Your monthly payment</span><div className="calc-big">{naira(monthly(product.price,months))}</div></div><div style={{textAlign:"right"}}><span className="small">Term</span><div style={{fontWeight:700}}>{months} months</div></div></div><div className="calc-foot">Total with demonstration plan fee: {naira(monthly(product.price,months)*months)} · No hidden charges</div></div><div className="hero-actions"><button className="btn btn-primary" onClick={()=>{onAdd(product);onToast(`${product.name} added to your cart`)}} data-testid="button-add-detail">Add to cart <ShoppingBag size={15}/></button><Link href="/apply" className="btn btn-ghost" data-testid="link-apply-detail">Apply for this gadget</Link></div><div className="divider" style={{margin:"25px 0 17px"}}/><h3 className="display" style={{fontSize:18}}>What’s inside</h3><ul className="fine muted" style={{paddingLeft:18,lineHeight:2}}>{product.specs.map(s=><li key={s}>{s}</li>)}</ul></div></div></section></>;
}

function Plans(){ const [months,setMonths]=useState(6); return <><PageHero eyebrow="Payment plans" title="A plan should feel like a plan, not a puzzle." text="See the numbers before you commit. Pick a pace, understand the total, and keep moving."/><section className="section"><div className="container"><div className="section-head"><div><div className="eyebrow">Three ways to pace it</div><h2>Choose your comfortable.</h2></div><p className="muted">Illustrative terms shown for demonstration. Final eligibility and terms are confirmed during application.</p></div><div className="plan-grid"><PlanCard name="Easy Start" months="3 months" rate="Fast track" text="For smaller purchases or when you want to finish sooner."/><PlanCard name="Steady Pace" months="6 months" rate="Most chosen" text="A balanced monthly commitment for your next everyday upgrade." featured/><PlanCard name="Room to Breathe" months="12 months" rate="Light monthly" text="For bigger gadgets when flexibility matters most."/></div></div></section><section className="section band"><div className="container" style={{maxWidth:650}}><div className="eyebrow">A simple example</div><h2 className="display" style={{fontSize:38,margin:"10px 0"}}>See your monthly number.</h2><p className="muted">Try the slider on a sample gadget. The estimate includes our illustrative 8% plan fee.</p><select className="select" value={months} onChange={e=>setMonths(Number(e.target.value))} data-testid="select-plan-example"><option value={3}>3 monthly payments</option><option value={6}>6 monthly payments</option><option value={9}>9 monthly payments</option><option value={12}>12 monthly payments</option></select><div className="dashboard-card" style={{marginTop:15,display:"flex",justifyContent:"space-between",alignItems:"center",gap:20}}><div><span className="small muted">MacBook Air M2 · {months} months</span><div className="calc-big" style={{color:"var(--indigo)"}}>{naira(monthly(1280000,months))}<span className="small muted"> / month</span></div></div><Link href="/apply" className="btn btn-primary" data-testid="link-plans-apply">Start an application <ArrowRight size={15}/></Link></div></div></section></>; }
function PlanCard({name,months,rate,text,featured=false}:{name:string;months:string;rate:string;text:string;featured?:boolean}) { return <div className={`plan-card ${featured?"featured":""}`}>{featured&&<span className="product-badge">Most popular</span>}<div className="eyebrow">{rate}</div><h3>{name}</h3><div className="rate">{months}</div><p className="fine muted">{text}</p><ul><li><Check size={15}/> Clear monthly estimate</li><li><Check size={15}/> No surprise fees</li><li><Check size={15}/> Support when you need it</li></ul><Link href="/how-it-works" className="btn btn-ghost" style={{width:"100%"}} data-testid={`link-plan-${name.toLowerCase().replaceAll(" ","-")}`}>Learn about this plan</Link></div>; }

function HowItWorks(){ return <><PageHero eyebrow="How it works" title="From “I want it” to “it’s mine”." text="A clear four-step path, with real people and plain numbers at every turn."/><section className="section"><div className="container"><div className="step-grid">{[["01","Choose your gadget","Browse the collection and find the thing that fits your work, play, or next chapter."],["02","Pick your pace","Use the calculator to choose 3, 6, 9, or 12 months. See your monthly estimate before you apply."],["03","Tell us a little","Complete a short application so we can understand your plan. It takes a few minutes."],["04","Get moving","Once approved, we prepare your gadget for delivery. Then you pay your agreed amount monthly."]].map(([n,t,d])=><div className="step" key={n}><span className="step-num">{n}</span><h3>{t}</h3><p>{d}</p></div>)}</div></div></section><section className="section band"><div className="container feature-grid"><div className="feature-card"><ShieldCheck size={24}/><h3>Transparent by default</h3><p className="muted">Every product page shows the price, term, estimated monthly payment, and illustrative total together.</p></div><div className="feature-card"><Wallet size={24}/><h3>Built around cash flow</h3><p className="muted">A good plan is one you can live with comfortably—not one that stretches you thin.</p></div><div className="feature-card"><MessageCircle size={24}/><h3>Questions are welcome</h3><p className="muted">We would rather explain something twice than leave you guessing.</p></div></div></section><section className="section"><div className="narrow"><div className="eyebrow">Worth knowing</div><h2 className="display" style={{fontSize:38}}>This is a demonstration experience.</h2><p className="muted" style={{lineHeight:1.8}}>The Gentlemen Series in this preview uses mock gadgets, applications, and payment schedules. No payment is processed, and no application is submitted to a live service.</p><Link href="/shop" className="btn btn-primary" data-testid="link-how-shop">Find your gadget <ArrowRight size={15}/></Link></div></section></>; }

function About(){ return <><PageHero eyebrow="Our story" title="Good tech should feel within reach." text="The Gentlemen Series started with a simple frustration: buying a great gadget in Nigeria should not require a spreadsheet, a favour, or a leap of faith."/><section className="section"><div className="container form-layout"><div><div className="eyebrow">Why we exist</div><h2 className="display" style={{fontSize:48}}>Less pressure.<br/>More possibility.</h2><p className="muted" style={{lineHeight:1.85}}>We are building a warmer kind of gadget marketplace—one that respects your ambition and your monthly reality. Whether you are upgrading your work setup in Yaba, getting a first laptop for school in Ibadan, or making room for game night in Port Harcourt, the point is the same: you deserve options.</p><p className="muted" style={{lineHeight:1.85}}>That means honest descriptions, useful support, and payment plans written for people—not for legal departments.</p></div><div className="side-card"><Sparkles size={25} color="var(--mint)"/><h3>Our north star</h3><p className="muted">Make the next good thing feel possible.</p><ul className="side-list"><li><BadgeCheck size={16}/> Tell the truth about the total.</li><li><Heart size={16}/> Treat every customer like a neighbour.</li><li><Zap size={16}/> Keep the experience quick and clear.</li></ul></div></div></section><section className="section-tight mint-band"><div className="container numbers"><div className="number-card"><b>Human</b><span>support, not scripts</span></div><div className="number-card"><b>Clear</b><span>terms, not tricks</span></div><div className="number-card"><b>Local</b><span>made with Nigeria in mind</span></div></div></section></>; }

function Contact(){ const [open,setOpen]=useState<number|null>(0); const [sent,setSent]=useState(false); const faqs=[["Are the prices real?","This is a front-end demonstration, so all products, prices, applications, and payment terms are mock data. No money is collected."],["How do installment plans work?","Choose a gadget, select a term, and review the illustrative monthly amount. In a live version, the application would then be reviewed before delivery."],["Where do you deliver?","The demo is designed around nationwide Nigerian delivery, from Lagos to Kano and everywhere in between."],["Can I pay early?","In a live plan, early repayment options would be shown clearly in your agreement. This preview does not process payments."]]; return <><PageHero eyebrow="Contact" title="Bring us your question." text="Whether you need help choosing a laptop or want us to explain a plan again, we are listening."/><section className="section"><div className="container form-layout"><form className="form-card" onSubmit={e=>{e.preventDefault();setSent(true)}}><h2>Send a message</h2>{sent?<div className="empty"><Check size={28}/><h3 className="display">Message received.</h3><p className="muted">We will get back to you in this demo experience.</p><button type="button" className="btn btn-primary" onClick={()=>setSent(false)} data-testid="button-send-another">Send another</button></div>:<><div className="field-grid"><div className="field"><label htmlFor="contact-name">Your name</label><input id="contact-name" className="input" required placeholder="Ada Okafor" data-testid="input-contact-name"/></div><div className="field"><label htmlFor="contact-email">Email address</label><input id="contact-email" className="input" type="email" required placeholder="ada@email.com" data-testid="input-contact-email"/></div><div className="field full"><label htmlFor="contact-message">How can we help?</label><textarea id="contact-message" className="textarea" required placeholder="Tell us what is on your mind..." data-testid="input-contact-message"/></div></div><button className="btn btn-primary" type="submit" data-testid="button-submit-contact">Send message <Send size={15}/></button></>}</form><div><div className="side-card" style={{marginBottom:20}}><Headphones size={23} color="var(--mint)"/><h3>Talk to a human</h3><p className="muted">Mon–Fri, 9am–5pm<br/>hello@thegentlemen.ng<br/>Lagos, Nigeria</p></div><div className="faq"><div className="eyebrow" style={{margin:"12px 0 10px"}}>Good to know</div>{faqs.map(([q,a],i)=><div className="faq-item" key={q}><button className="faq-q" onClick={()=>setOpen(open===i?null:i)} data-testid={`button-faq-${i}`}>{q}{open===i?<Minus size={16}/>:<Plus size={16}/>}</button>{open===i&&<div className="faq-a">{a}</div>}</div>)}</div></div></div></section></>; }

function Apply({onToast}:{onToast:(s:string)=>void}){ const [submitted,setSubmitted]=useState(false); const [form,setForm]=useState({name:"",email:"",phone:"",city:"Lagos",employment:"",gadget:"",income:""}); const [errors,setErrors]=useState<string[]>([]); const update=(k:string,v:string)=>setForm({...form,[k]:v}); const submit=(e:FormEvent)=>{e.preventDefault();const missing=Object.entries(form).filter(([,v])=>!v).map(([k])=>k);setErrors(missing);if(!missing.length){localStorage.setItem("gs-application",JSON.stringify(form));setSubmitted(true);onToast("Application saved in this demo");}}; return <><PageHero eyebrow="Apply" title="Your next gadget starts here." text="A short, friendly application. No credit check or real submission happens in this demo."/><section className="section"><div className="container form-layout"><form className="form-card" onSubmit={submit}><h2>Tell us about you</h2><p className="fine muted">All fields are required for the demo application.</p><div className="field-grid"><Field label="Full name" value={form.name} onChange={v=>update("name",v)} id="name" error={errors.includes("name")}/><Field label="Email address" type="email" value={form.email} onChange={v=>update("email",v)} id="email" error={errors.includes("email")}/><Field label="Phone number" value={form.phone} onChange={v=>update("phone",v)} id="phone" error={errors.includes("phone")}/><div className="field"><label htmlFor="city">City</label><select id="city" className="select" value={form.city} onChange={e=>update("city",e.target.value)} data-testid="select-city"><option>Lagos</option><option>Abuja</option><option>Ibadan</option><option>Port Harcourt</option><option>Kano</option></select></div><div className="field"><label htmlFor="employment">What best describes you?</label><select id="employment" className="select" value={form.employment} onChange={e=>update("employment",e.target.value)} data-testid="select-employment"><option value="">Select one</option><option>Employed</option><option>Self-employed</option><option>Student</option><option>Business owner</option></select>{errors.includes("employment")&&<span className="error">Please choose one</span>}</div><div className="field"><label htmlFor="income">Monthly income range</label><select id="income" className="select" value={form.income} onChange={e=>update("income",e.target.value)} data-testid="select-income"><option value="">Select one</option><option>Under ₦150,000</option><option>₦150,000–₦300,000</option><option>₦300,000–₦600,000</option><option>Above ₦600,000</option></select>{errors.includes("income")&&<span className="error">Please choose one</span>}</div><div className="field full"><label htmlFor="gadget">Which gadget are you interested in?</label><select id="gadget" className="select" value={form.gadget} onChange={e=>update("gadget",e.target.value)} data-testid="select-gadget"><option value="">Choose a gadget</option>{products.map(p=><option key={p.id} value={p.id}>{p.name} · {naira(p.price)}</option>)}</select>{errors.includes("gadget")&&<span className="error">Please choose a gadget</span>}</div></div>{errors.length>0&&<p className="error" data-testid="text-application-error">Please complete the highlighted fields.</p>}<button type="submit" className="btn btn-primary" data-testid="button-submit-application">Review application <ArrowRight size={15}/></button></form><div className="side-card"><ClipboardList size={24} color="var(--mint)"/><h3>A little context helps.</h3><p className="muted">Your answers help us shape a payment plan that feels responsible and realistic.</p><ul className="side-list"><li><ShieldCheck size={16}/> Your data stays in this browser demo.</li><li><Clock3 size={16}/> It takes about 3 minutes.</li><li><MessageCircle size={16}/> We keep the next step clear.</li></ul></div></div></section>{submitted&&<div className="modal-backdrop"><div className="modal"><div className="modal-head"><div><div className="eyebrow">Demo application</div><h2>That felt easy.</h2></div><button className="close" onClick={()=>setSubmitted(false)} aria-label="Close success modal" data-testid="button-close-application-modal"><X size={18}/></button></div><div className="empty" style={{padding:"25px 15px",border:0}}><div className="avatar" style={{margin:"0 auto 14px"}}><Check size={19}/></div><p className="muted">Your demonstration application for <strong>{products.find(p=>p.id===form.gadget)?.name}</strong> has been saved locally. Nothing has been submitted or charged.</p><Link href="/dashboard/applications" className="btn btn-primary" onClick={()=>setSubmitted(false)} data-testid="link-view-application">View my application</Link></div></div></div>}</>; }
function Field({label,value,onChange,id,type="text",error=false}:{label:string;value:string;onChange:(v:string)=>void;id:string;type?:string;error?:boolean}){return <div className="field"><label htmlFor={id}>{label}</label><input id={id} type={type} className="input" value={value} onChange={e=>onChange(e.target.value)} aria-invalid={error} data-testid={`input-application-${id}`}/>{error&&<span className="error">This field is required</span>}</div>}

function Login({onToast}:{onToast:(s:string)=>void}){ const [,setLocation]=useLocation(); const [email,setEmail]=useState(""); return <section className="section" style={{minHeight:"calc(100dvh - 114px)",display:"grid",placeItems:"center",background:"var(--wash)"}}><div className="form-card" style={{width:"min(450px,100%)"}}><div className="brand" style={{marginBottom:28}}><span className="brand-mark">G</span><span>The Gentlemen<small>Series / demo sign in</small></span></div><div className="eyebrow">Welcome back</div><h1 className="display" style={{fontSize:39,margin:"10px 0"}}>Your gadgets,<br/>in one place.</h1><p className="muted fine">Sign in to see your schedule, applications, and support messages.</p><form onSubmit={e=>{e.preventDefault();localStorage.setItem("gs-user",email||"Ada Okafor");onToast("Signed in to demo dashboard");setLocation("/dashboard")}}><div className="field"><label htmlFor="login-email">Email address</label><input id="login-email" className="input" type="email" required value={email} onChange={e=>setEmail(e.target.value)} placeholder="you@email.com" data-testid="input-login-email"/></div><div className="field"><label htmlFor="login-password">Password</label><input id="login-password" className="input" type="password" required placeholder="Any password works in the demo" data-testid="input-login-password"/></div><button className="btn btn-primary" style={{width:"100%"}} type="submit" data-testid="button-submit-login">Continue to dashboard <ArrowRight size={15}/></button></form><p className="small muted" style={{textAlign:"center",marginTop:20}}>Demo only · no account or password is sent anywhere.</p></div></section>; }

function CartDrawer({items,onClose,onQty,onRemove,onCheckout}:{items:CartItem[];onClose:()=>void;onQty:(id:string,n:number)=>void;onRemove:(id:string)=>void;onCheckout:()=>void}){const total=items.reduce((s,i)=>s+i.product.price*i.qty,0);return <><div className="cart-overlay" onClick={onClose}/><aside className="cart-drawer" aria-label="Shopping cart"><div className="modal-head"><div><div className="eyebrow">Your shortlist</div><h2>Cart <span className="muted small">({items.length})</span></h2></div><button className="close" onClick={onClose} aria-label="Close cart" data-testid="button-close-cart"><X size={18}/></button></div>{items.length?<>{items.map(i=><div className="cart-line" key={i.product.id} data-testid={`cart-item-${i.product.id}`}><div className="cart-thumb"><ProductArt product={i.product}/></div><div style={{flex:1}}><h4>{i.product.name}</h4><div className="price">{naira(i.product.price)}</div><div className="qty"><button onClick={()=>onQty(i.product.id,i.qty-1)} aria-label="Decrease quantity" data-testid={`button-decrease-${i.product.id}`}><Minus size={12}/></button><span className="small">{i.qty}</span><button onClick={()=>onQty(i.product.id,i.qty+1)} aria-label="Increase quantity" data-testid={`button-increase-${i.product.id}`}><Plus size={12}/></button><button onClick={()=>onRemove(i.product.id)} aria-label={`Remove ${i.product.name}`} style={{marginLeft:"auto",border:0,background:"none",color:"var(--rose)"}} data-testid={`button-remove-${i.product.id}`}><Trash2 size={14}/></button></div></div></div>)}<div style={{marginTop:25}}><div className="calc-row"><span className="muted">Estimated total</span><strong className="price">{naira(total)}</strong></div><p className="small muted">Or from {naira(monthly(total))}/month on a 6 month demonstration plan.</p><button className="btn btn-primary" style={{width:"100%"}} onClick={onCheckout} data-testid="button-cart-checkout">Continue to application <ArrowRight size={15}/></button></div></>:<div className="empty" style={{marginTop:40}}><ShoppingBag size={28}/><h3 className="display">Your cart is taking a breather.</h3><p className="muted">Add something good and it will show up here.</p><Link href="/shop" className="btn btn-primary" onClick={onClose} data-testid="link-empty-cart-shop">Browse gadgets</Link></div>}</aside></>; }

function DashboardShell({children}:{children:ReactNode}){ const [,setLocation]=useLocation(); const [location]=useLocation(); const links=[["/dashboard","Overview",LayoutDashboard],["/dashboard/gadgets","My gadgets",Package],["/dashboard/applications","Applications",ClipboardList],["/dashboard/profile","Profile",User],["/dashboard/support","Support",MessageCircle]] as const; return <div className="dashboard-wrap"><div className="container dashboard-grid"><aside className="dash-nav"><div className="dash-user"><div className="avatar">AO</div><b data-testid="text-dashboard-user">Ada Okafor</b><span>Member since March 2024</span></div><div className="dash-links">{links.map(([href,label,Icon])=><Link key={href} href={href} className={location===href?"active":""} data-testid={`link-dashboard-${label.toLowerCase().replaceAll(" ","-")}`}><Icon size={15}/>{label}</Link>)}</div><button className="btn btn-ghost" style={{width:"100%",color:"#fff",borderColor:"rgba(255,255,255,.2)",marginTop:18}} onClick={()=>{localStorage.removeItem("gs-user");setLocation("/login")}} data-testid="button-dashboard-logout">Sign out</button></aside><main className="dash-main">{children}</main></div></div>; }
function Dashboard(){return <DashboardShell><div className="eyebrow">Monday, 18 March 2024</div><h1>Good morning, Ada.</h1><p className="muted">Here is the shape of your gadget journey.</p><div className="metric-grid"><div className="metric"><div className="metric-label"><span>Next payment</span><Wallet size={15}/></div><b>{naira(142300)}</b><span className="small muted">Due 28 March 2024</span></div><div className="metric"><div className="metric-label"><span>Plan progress</span><BarChart3 size={15}/></div><b>4 <span className="small muted">of 6 paid</span></b><div className="progress"><span style={{width:"66%"}}/></div></div><div className="metric"><div className="metric-label"><span>Active gadgets</span><Package size={15}/></div><b>1</b><span className="small muted">MacBook Air M2</span></div></div><div className="dash-columns"><div className="dashboard-card"><div className="section-head" style={{marginBottom:5}}><h2>Payment schedule</h2><Link href="/dashboard/gadgets" className="small" data-testid="link-dashboard-schedule">View gadget <ArrowRight size={12}/></Link></div>{[["28 Mar 2024","₦142,300","Paid"],["28 Apr 2024","₦142,300","Paid"],["28 May 2024","₦142,300","Paid"],["28 Jun 2024","₦142,300","Paid"],["28 Jul 2024","₦142,300","Next up"],["28 Aug 2024","₦142,300","Upcoming"]].map(([date,amount,status],i)=><div className="payment-line" key={date}><div><span className={`payment-dot ${i>3?"pending":""}`}/><div><strong>{date}</strong><span>MacBook Air M2</span></div></div><div style={{textAlign:"right"}}><strong>{amount}</strong><span className={`status ${i>3?"pending":""}`}>{status}</span></div></div>)}</div><div><div className="dashboard-card" style={{marginBottom:17}}><h2>Keep going</h2><div className="progress" style={{height:12,margin:"20px 0 11px"}}><span style={{width:"66%"}}/></div><p className="fine muted">You are 2 payments away from owning your MacBook Air M2 outright.</p><Link href="/dashboard/support" className="btn btn-soft" data-testid="link-dashboard-support">Need help? Talk to us</Link></div><div className="dashboard-card"><h2>Good to know</h2><p className="fine muted">This dashboard uses simulated data. Any payment action below is a demonstration only.</p><Link href="/plans" className="small" data-testid="link-dashboard-plans">Review payment plans <ArrowRight size={12}/></Link></div></div></div></DashboardShell>; }

function DashboardGadgets(){const [paying,setPaying]=useState(false);const [paid,setPaid]=useState(false);return <DashboardShell><div className="eyebrow">Your collection</div><h1>My gadgets</h1><p className="muted">The things you are paying for, all in one place.</p><div className="dashboard-card"><div className="payment-line"><div><div className="cart-thumb" style={{marginRight:3}}><ProductArt product={products[4]}/></div><div><strong>MacBook Air M2</strong><span>Apple · Midnight · 256GB</span></div></div><span className="status pending">{paid?"5 of 6 paid":"4 of 6 paid"}</span></div><div style={{margin:"20px 0 8px",display:"flex",justifyContent:"space-between"}}><span className="small muted">Ownership progress</span><b className="small">{paid?"83%":"66%"}</b></div><div className="progress"><span style={{width:paid?"83%":"66%"}}/></div><div className="hero-actions"><button className="btn btn-primary" onClick={()=>setPaying(true)} data-testid="button-pay-gadget">{paid?"Payment simulated":"Make a simulated payment"} <CreditCard size={15}/></button><Link href="/dashboard/support" className="btn btn-ghost" data-testid="link-gadget-support">Ask about this gadget</Link></div></div>{paying&&<div className="modal-backdrop"><div className="modal"><div className="modal-head"><div><div className="eyebrow">Demo payment</div><h2>Make this month’s payment?</h2></div><button className="close" onClick={()=>setPaying(false)} aria-label="Close payment modal" data-testid="button-close-payment-modal"><X size={18}/></button></div><div className="dashboard-card" style={{background:"var(--wash)"}}><div className="small muted">MacBook Air M2 · payment 5 of 6</div><div className="calc-big" style={{color:"var(--indigo)",marginTop:8}}>₦142,300</div><p className="fine muted">This is a simulated payment. No money will be moved.</p></div><button className="btn btn-primary" style={{width:"100%",marginTop:17}} onClick={()=>{setPaid(true);setPaying(false)}} data-testid="button-confirm-payment">Confirm simulated payment <Check size={15}/></button></div></div>}</DashboardShell>; }
function DashboardApplications(){return <DashboardShell><div className="eyebrow">Your journey</div><h1>Applications</h1><p className="muted">A quiet paper trail of the gadgets you have considered.</p><div className="dashboard-card"><div className="table-wrap"><table className="data-table"><thead><tr><th>Gadget</th><th>Date</th><th>Plan</th><th>Status</th></tr></thead><tbody><tr><td><strong>MacBook Air M2</strong><br/><span className="small muted">APL-240318</span></td><td>18 Mar 2024</td><td>6 months</td><td><span className="status">Approved</span></td></tr><tr><td><strong>iPhone 15</strong><br/><span className="small muted">APL-240212</span></td><td>12 Feb 2024</td><td>6 months</td><td><span className="status review">Not continued</span></td></tr></tbody></table></div><div className="empty" style={{marginTop:18,padding:"30px"}}><p className="muted">Ready for a fresh shortlist?</p><Link href="/shop" className="btn btn-soft" data-testid="link-applications-shop">Browse gadgets</Link></div></div></DashboardShell>; }
function DashboardProfile(){ const [saved,setSaved]=useState(false); return <DashboardShell><div className="eyebrow">Account</div><h1>Profile</h1><p className="muted">Keep your details close and your choices yours.</p><div className="form-card"><div className="field-grid"><Field label="Full name" id="profile-name" value="Ada Okafor" onChange={()=>{}}/><Field label="Email address" id="profile-email" value="ada.okafor@email.com" onChange={()=>{}}/><Field label="Phone number" id="profile-phone" value="+234 803 555 0182" onChange={()=>{}}/><Field label="City" id="profile-city" value="Lagos" onChange={()=>{}}/></div><button className="btn btn-primary" onClick={()=>setSaved(true)} data-testid="button-save-profile">{saved?"Details saved":"Save details"} <Check size={15}/></button></div></DashboardShell>; }
function DashboardSupport(){ const [sent,setSent]=useState(false); return <DashboardShell><div className="eyebrow">We are here</div><h1>Support</h1><p className="muted">No question is too small when it is about your money or your gadget.</p><div className="form-layout"><form className="form-card" onSubmit={e=>{e.preventDefault();setSent(true)}}><h2>Start a conversation</h2>{sent?<div className="empty" style={{padding:"30px 10px"}}><Check size={26}/><h3 className="display">Sent to the demo inbox.</h3><button type="button" className="btn btn-soft" onClick={()=>setSent(false)} data-testid="button-new-support">New message</button></div>:<><div className="field"><label htmlFor="support-topic">Topic</label><select className="select" id="support-topic" data-testid="select-support-topic"><option>Payment question</option><option>Gadget delivery</option><option>Change my details</option><option>Something else</option></select></div><div className="field"><label htmlFor="support-message">Message</label><textarea id="support-message" className="textarea" required placeholder="How can we help?" data-testid="input-support-message"/></div><button className="btn btn-primary" type="submit" data-testid="button-submit-support">Send message <Send size={15}/></button></>}</form><div className="side-card"><Headphones size={23} color="var(--mint)"/><h3>We reply with care.</h3><p className="muted">Our demo support team is available Monday to Friday, 9am to 5pm.</p><div className="divider" style={{background:"rgba(255,255,255,.2)",margin:"20px 0"}}/><p className="small muted">hello@thegentlemen.ng<br/>+234 800 000 0000</p></div></div></DashboardShell>; }

function Admin(){return <div className="dashboard-wrap"><div className="container"><div className="section-head"><div><div className="eyebrow">Internal preview</div><h1 className="display" style={{fontSize:40,margin:"10px 0"}}>Admin overview</h1><p className="muted">A frontend-only snapshot of the marketplace pulse.</p></div><Link href="/" className="btn btn-ghost" data-testid="link-admin-home">Back to storefront</Link></div><div className="metric-grid"><div className="metric"><div className="metric-label"><span>Applications this week</span><ClipboardList size={15}/></div><b>47</b><span className="small" style={{color:"var(--mint-deep)"}}>↑ 12% from last week</span></div><div className="metric"><div className="metric-label"><span>Active plans</span><Wallet size={15}/></div><b>182</b><span className="small muted">₦24.8m outstanding</span></div><div className="metric"><div className="metric-label"><span>Gadgets delivered</span><Truck size={15}/></div><b>96</b><span className="small muted">Across 8 cities</span></div></div><div className="dash-columns"><div className="dashboard-card"><h2>Recent applications</h2><div className="table-wrap"><table className="data-table"><thead><tr><th>Applicant</th><th>Gadget</th><th>Amount</th><th>Status</th></tr></thead><tbody>{[["Chinonso Eze","iPhone 15","₦965,000","review"],["Mariam Bello","PS5 Slim","₦920,000","Approved"],["Tobi Adeyemi","Galaxy S24","₦825,000","Approved"],["Sade Williams","MacBook Air M2","₦1,280,000","review"]].map(([a,g,am,s])=><tr key={a}><td><strong>{a}</strong><br/><span className="small muted">Today, 10:4{Math.floor(Math.random()*9)}</span></td><td>{g}</td><td>{am}</td><td><span className={`status ${s==="review"?"review":""}`}>{s==="review"?"Needs review":s}</span></td></tr>)}</tbody></table></div></div><div className="dashboard-card"><h2>Inventory watch</h2>{[["iPhone 15","18 units","healthy"],["PS5 Slim","4 units","low"],["MacBook Air M2","11 units","healthy"],["AirPods Pro","2 units","low"]].map(([n,q,s])=><div className="payment-line" key={n}><div><div className="payment-dot" style={{background:s==="low"?"var(--amber)":"var(--mint-deep)"}}/><div><strong>{n}</strong><span>{q}</span></div></div><span className={`status ${s==="low"?"pending":""}`}>{s}</span></div>)}</div></div></div></div>; }

function AppContent(){ const [cart,setCart]=useState<CartItem[]>(getCart); const [drawer,setDrawer]=useState(false); const [toast,setToast]=useState(""); const [location,setLocation]=useLocation(); useEffect(()=>{localStorage.setItem("gs-cart",JSON.stringify(cart))},[cart]); useEffect(()=>{if(!toast)return; const t=setTimeout(()=>setToast(""),2800); return()=>clearTimeout(t)},[toast]); const add=(product:Product)=>{setCart(old=>{const found=old.find(i=>i.product.id===product.id);return found?old.map(i=>i.product.id===product.id?{...i,qty:i.qty+1}:i):[...old,{product,qty:1}]});setToast(`${product.name} added to cart`)}; const qty=(id:string,n:number)=>setCart(c=>n<1?c.filter(i=>i.product.id!==id):c.map(i=>i.product.id===id?{...i,qty:n}:i)); const remove=(id:string)=>setCart(c=>c.filter(i=>i.product.id!==id)); const checkout=()=>{setDrawer(false);setLocation("/apply");setToast("Your shortlist is ready for application")}; const common={onAdd:add,onToast:setToast}; return <><Nav cartCount={cart.reduce((s,i)=>s+i.qty,0)} onCart={()=>setDrawer(true)}/><Switch><Route path="/" component={()=> <Home {...common}/>}/><Route path="/shop" component={()=> <Shop {...common}/>}/><Route path="/product/:id" component={()=> <ProductDetail {...common}/>}/><Route path="/plans" component={Plans}/><Route path="/how-it-works" component={HowItWorks}/><Route path="/about" component={About}/><Route path="/contact" component={Contact}/><Route path="/apply" component={()=> <Apply onToast={setToast}/>}/><Route path="/login" component={()=> <Login onToast={setToast}/>}/><Route path="/dashboard" component={Dashboard}/><Route path="/dashboard/gadgets" component={DashboardGadgets}/><Route path="/dashboard/applications" component={DashboardApplications}/><Route path="/dashboard/profile" component={DashboardProfile}/><Route path="/dashboard/support" component={DashboardSupport}/><Route path="/admin" component={Admin}/><Route component={()=> <NotFoundPage/>}/></Switch>{!["/login","/dashboard","/dashboard/gadgets","/dashboard/applications","/dashboard/profile","/dashboard/support","/admin"].includes(location)&&<Footer/>}{drawer&&<CartDrawer items={cart} onClose={()=>setDrawer(false)} onQty={qty} onRemove={remove} onCheckout={checkout}/>} {toast&&<div className="toast success" role="status" data-testid="status-toast">{toast}</div>}</>; }
function NotFoundPage(){return <section className="section"><div className="empty narrow"><CircleHelp size={30}/><h1 className="display">This page wandered off.</h1><p className="muted">Let us point you back to something good.</p><Link href="/" className="btn btn-primary" data-testid="link-not-found-home">Back home</Link></div></section>}
function App(){return <QueryClientProvider client={queryClient}><TooltipProvider><WouterRouter base={import.meta.env.BASE_URL.replace(/\/$/,"")}><ErrorBoundary><AppContent/></ErrorBoundary></WouterRouter><Toaster/></TooltipProvider></QueryClientProvider>}
export default App;